  'help.type.security': 'Seguretat',
  'help.type.other': 'Altres',
  'help.faq.cantLogin.q': 'No puc accedir al meu compte',
  'help.faq.cantLogin.a': 'Verifica si estàs utilitzant l\'email i la contrasenya correctes. Si has oblidat la contrasenya, clica a "Has oblidat la contrasenya?" a la pantalla d\'inici de sessió. Si el problema persisteix, crea un ticket de suport.',
  'help.faq.notReceiving.q': 'No estic rebent emails',
  'help.faq.notReceiving.a': 'Comprova primer la carpeta de Spam. Assegura\'t que el teu emmagatzematge no estigui ple. Si el problema continua, confirma que el remitent té l\'adreça correcta i crea un ticket.',
  'help.faq.cantSend.q': 'No puc enviar emails',
  'help.faq.cantSend.a': 'Verifica la teva connexió a internet i si l\'adreça del destinatari és correcta. Comprova que els adjunts no superin els 25MB. Prova-ho de nou en uns minuts.',
  'help.faq.forgotPassword.q': 'He oblidat la meva contrasenya',
  'help.faq.forgotPassword.a': 'A la pantalla d\'inici de sessió, clica a "Has oblidat la contrasenya?" i segueix les instruccions per restablir la teva contrasenya per l\'email de recuperació.',
  'help.faq.accountSecurity.q': 'Crec que el meu compte ha estat compromès',
  'help.faq.accountSecurity.a': 'Canvia la teva contrasenya immediatament. Comprova la carpeta Enviats per missatges que no has enviat. Activa l\'autenticació en dues etapes a Configuracions > Seguretat. Si cal, crea un ticket urgent.',
  'help.faq.appAccess.q': 'Com accedeixo a l\'app al mòbil?',
  'help.faq.appAccess.a': 'Pots accedir al Chatyy pel navegador a chatyy.com.br, o baixar la nostra app a la botiga d\'aplicacions del teu dispositiu.',
  'privacy.title': 'Política de Privacitat',
  'privacy.subtitle': 'Com protegim i tractem les teves dades',
  'privacy.lastUpdated': 'Última actualització: Març 2026',
  'privacy.dataCollection.title': 'Recollida de Dades',
  'privacy.dataCollection.body': 'Recollim només la informació necessària per al servei d\'email: el teu nom, adreça d\'email i el contingut dels missatges enviats i rebuts. No venem ni compartim les teves dades personals amb tercers per a fins de màrqueting.',
  'privacy.dataUsage.title': 'Com Fem Servir les Teves Dades',
  'privacy.dataUsage.body': 'Les teves dades s\'utilitzen exclusivament per operar i millorar el servei d\'email, incloent la entrega de missatges, filtratge de spam, funcions d\'IA (amb el teu consentiment) i seguretat del compte.',
  'privacy.dataSecurity.title': 'Seguretat de les Dades',
  'privacy.dataSecurity.body': 'Fem servir xifratge estàndard de la indústria (TLS/SSL) per a totes les dades en trànsit i en repòs. Les sessions estan protegides amb tokens xifrats i protecció CSRF. Auditem regularment les nostres pràctiques de seguretat.',
  'privacy.cookies.title': 'Cookies i Emmagatzematge Local',
  'privacy.cookies.body': 'Fem servir cookies essencials i emmagatzematge local per mantenir la teva sessió, recordar les teves preferències (tema, idioma) i proporcionar una experiència fluida. No fem servir cookies de seguiment de tercers.',
  'privacy.thirdParties.title': 'Serveis de Tercers',
  'privacy.thirdParties.body': 'Podem utilitzar serveis de tercers per funcionalitats específiques com IA (Anthropic Claude) i notificacions push. Aquests serveis segueixen les seves pròpies polítiques de privacitat i processen només el mínim de dades necessari.',
  'privacy.rights.title': 'Els Teus Drets',
  'privacy.rights.body': 'Tens el dret d\'accedir, corregir, exportar o eliminar les teves dades personals en qualsevol moment. Pots gestionar les teves dades a Configuracions o contactant amb el nostre suport.',
  'privacy.contact.title': 'Contacta\'ns',
  'privacy.contact.body': 'Per qüestions de privacitat o sol·licituds de dades, contacta\'ns a privacy@chatyy.com.br. Respondrem en un màxim de 30 dies.',
  'terms.title': 'Termes de Servei',
  'terms.subtitle': 'Directrius d\'ús del Chatyy',
  'terms.lastUpdated': 'Última actualització: Març 2026',
  'terms.acceptance.title': 'Acceptació dels Termes',
  'terms.acceptance.body': 'En accedir o utilitzar el Chatyy, acceptes aquests Termes de Servei. Si no acceptes cap part d\'aquests termes, no utilitzis el servei.',
  'terms.services.title': 'Descripció dels Serveis',
  'terms.services.body': 'El Chatyy proporciona serveis de comunicació per email incloent enviament, recepció i gestió d\'emails, a més de funcions d\'IA, integració amb calendari i videoconferència.',
  'terms.accounts.title': 'Comptes d\'Usuari',
  'terms.accounts.body': 'Ets responsable de mantenir la seguretat de les teves credencials. No comparteixis la teva contrasenya ni permetis accés no autoritzat al teu compte. Has de tenir almenys 13 anys per utilitzar aquest servei.',
  'terms.conduct.title': 'Ús Acceptable',
  'terms.conduct.body': 'Acceptes no utilitzar el servei per enviar spam, malware, phishing o qualsevol contingut il·legal. No intentis accedir a comptes d\'altres usuaris o interrompre la infraestructura del servei.',
  'terms.content.title': 'Propietat del Contingut',
  'terms.content.body': 'Manteniràs la propietat de tot el contingut que crees i envies pel servei. No reclamem propietat sobre els teus emails o adjunts. Podem processar el contingut segons sigui necessari per proporcionar el servei.',
  'terms.limitation.title': 'Limitació de Responsabilitat',
  'terms.limitation.body': 'El Chatyy es proporciona "tal qual". Busquem un 99,9% de disponibilitat però no garantim servei ininterromput. No som responsables de danys indirectes, incidentals o conseqüents derivats de l\'ús del servei.',
  'terms.termination.title': 'Tancament de Compte',
  'terms.termination.body': 'Podem suspendre o tancar comptes que violen aquests termes. Pots eliminar el teu compte en qualsevol moment a Configuracions. Després del tancament, les teves dades seran eliminades en un màxim de 30 dies.',
  'terms.changes.title': 'Canvis als Termes',
  'terms.changes.body': 'Podem actualitzar aquests termes periòdicament. Notificarem sobre canvis significatius per email o notificació a l\'app. L\'ús continuat després dels canvis constitueix acceptació dels termes actualitzats.',
