  'plans.faqWhatIsPlus': 'Què és el Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'És el pla premium del Chatyy que protegeix totes les teves converses, fotos i vídeos. Amb el Chatyy One, fins i tot si esborres alguna cosa per error, pots recuperar-ho en fins a 30 dies. A més, guanyes 200GB d\'emmagatzematge, One AI com a assistent personal, i pots enviar fitxers de fins a 100MB.',
  'plans.faqCancelAnswer': 'El teu pla continuarà actiu fins al final del període pagat. Després d\'això, tornaràs al pla gratuït. Les teves fotos i vídeos que superin els 15GB es mantindran durant 30 dies més perquè puguis descarregar-los.',
